import './portal.css'
const theme=(()=>{try{return localStorage.getItem('personal-portal-theme')||'system'}catch{return 'system'}})()
const administrator=Array.isArray(currentUser.value?.profile.portal_roles)&&currentUser.value.profile.portal_roles.includes('portal-admin')
